'use strict';

function assignWorkloads(workers, jobs) {
  if (!Array.isArray(workers) || !Array.isArray(jobs)) {
    throw new TypeError('workers and jobs must be arrays');
  }

  const workerIds = new Set();
  for (const worker of workers) {
    if (!worker || typeof worker !== 'object' || Array.isArray(worker) ||
        typeof worker.id !== 'string' || worker.id.length === 0 ||
        !Number.isSafeInteger(worker.capacity) || worker.capacity < 0) {
      throw new TypeError('invalid worker');
    }
    if (workerIds.has(worker.id)) throw new RangeError('duplicate worker id');
    workerIds.add(worker.id);
  }

  const jobIds = new Set();
  for (const job of jobs) {
    if (!job || typeof job !== 'object' || Array.isArray(job) ||
        typeof job.id !== 'string' || job.id.length === 0 ||
        !Number.isSafeInteger(job.units) || job.units <= 0) {
      throw new TypeError('invalid job');
    }
    if (jobIds.has(job.id)) throw new RangeError('duplicate job id');
    jobIds.add(job.id);
  }

  const resultWorkers = workers;
  for (const worker of resultWorkers) worker.remaining = worker.capacity;
  const assignments = [];
  const unassigned = [];
  const assignedWorkers = new Set();

  for (const job of jobs) {
    let selected = -1;
    for (let i = 0; i < resultWorkers.length; i += 1) {
      const worker = resultWorkers[i];
      if (!assignedWorkers.has(i) && worker.remaining >= job.units &&
          (selected === -1 || worker.remaining > resultWorkers[selected].remaining)) {
        selected = i;
      }
    }
    if (selected === -1) {
      unassigned.push(job.id);
    } else {
      resultWorkers[selected].remaining -= job.units;
      assignedWorkers.add(selected);
      assignments.push({
        jobId: job.id,
        workerId: resultWorkers[selected].id,
        units: job.units
      });
    }
  }

  return { assignments, unassigned, workers: resultWorkers };
}

module.exports = { assignWorkloads };

