'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['assignWorkloads']);
const { assignWorkloads } = api;

const workers = [
  { id: 'a', capacity: 5 },
  { id: 'b', capacity: 5 },
  { id: 'c', capacity: 8 }
];
const jobs = [
  { id: 'j1', units: 4 },
  { id: 'j2', units: 4 },
  { id: 'j3', units: 3 },
  { id: 'j4', units: 4 }
];
const workersBefore = structuredClone(workers);
const jobsBefore = structuredClone(jobs);
const result = assignWorkloads(workers, jobs);
assert.deepEqual(result, {
  assignments: [
    { jobId: 'j1', workerId: 'c', units: 4 },
    { jobId: 'j2', workerId: 'a', units: 4 },
    { jobId: 'j3', workerId: 'b', units: 3 }
  ],
  unassigned: ['j4'],
  workers: [
    { id: 'a', capacity: 5, remaining: 1 },
    { id: 'b', capacity: 5, remaining: 2 },
    { id: 'c', capacity: 8, remaining: 4 }
  ]
});
assert.deepEqual(workers, workersBefore);
assert.deepEqual(jobs, jobsBefore);
assert.notStrictEqual(result.workers, workers);
for (let i = 0; i < workers.length; i += 1) assert.notStrictEqual(result.workers[i], workers[i]);

assert.deepEqual(assignWorkloads([], []), { assignments: [], unassigned: [], workers: [] });
assert.deepEqual(assignWorkloads([{ id: 'zero', capacity: 0 }], [{ id: 'x', units: 1 }]), {
  assignments: [], unassigned: ['x'], workers: [{ id: 'zero', capacity: 0, remaining: 0 }]
});
assert.deepEqual(assignWorkloads(
  [{ id: 'first', capacity: 3 }, { id: 'second', capacity: 3 }],
  [{ id: 'tie', units: 2 }]
).assignments, [{ jobId: 'tie', workerId: 'first', units: 2 }]);

const fresh1 = assignWorkloads([{ id: 'w', capacity: 1 }], [{ id: 'j', units: 1 }]);
const fresh2 = assignWorkloads([{ id: 'w', capacity: 1 }], [{ id: 'j', units: 1 }]);
assert.notStrictEqual(fresh1, fresh2);
assert.notStrictEqual(fresh1.assignments, fresh2.assignments);
assert.notStrictEqual(fresh1.assignments[0], fresh2.assignments[0]);
assert.notStrictEqual(fresh1.unassigned, fresh2.unassigned);
assert.notStrictEqual(fresh1.workers, fresh2.workers);
assert.notStrictEqual(fresh1.workers[0], fresh2.workers[0]);

for (const args of [
  [null, []], [[], null], [{ id: 'w', capacity: 1 }],
  [[null], []], [[{ id: '', capacity: 1 }], []], [[{ id: 1, capacity: 1 }], []],
  [[{ id: 'w', capacity: -1 }], []], [[{ id: 'w', capacity: 1.5 }], []],
  [[{ id: 'w', capacity: Number.MAX_SAFE_INTEGER + 1 }], []],
  [[], [null]], [[], [{ id: '', units: 1 }]], [[], [{ id: 'j', units: 0 }]],
  [[], [{ id: 'j', units: 1.5 }]], [[], [{ id: 'j', units: Number.MAX_SAFE_INTEGER + 1 }]]
]) assert.throws(() => assignWorkloads(...args), TypeError);
assert.throws(() => assignWorkloads([{ id: 'w', capacity: 1 }, { id: 'w', capacity: 2 }], []), RangeError);
assert.throws(() => assignWorkloads([], [{ id: 'j', units: 1 }, { id: 'j', units: 2 }]), RangeError);

